function splitBill(bill, tipPercent, people, roundUp = false) {
  const tip = bill * (tipPercent / 100);
  const total = bill + tip;
  const perPerson = roundUp ? Math.ceil(total / people) : total / people;
  return { tip, total, perPerson };
}

